<script setup lang="ts">
import {computed} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import Chart from '../components/Chart.vue'
import EventCard from '../components/EventCard.vue'
import {state,t,fmt,writeAccess,activeJob,runAnalysis} from '../state'
const router=useRouter()
const risks=computed(()=>state.events.filter(e=>e.sentiment==='risk'))
const opportunities=computed(()=>state.events.filter(e=>e.sentiment==='opportunity'))
const high=computed(()=>state.events.filter(e=>e.relevance>=80))
const sourceCount=computed(()=>new Set(state.events.map(e=>e.article?.source_name)).size)
const categories=computed(()=>{const counts:any={};state.events.forEach(e=>counts[e.category]=(counts[e.category]||0)+1);return Object.entries(counts).sort((a:any,b:any)=>b[1]-a[1])})
const labels=computed(()=>({macro:t('Macroeconomy','Макроэкономика'),regulation:t('Regulation','Регулирование'),competition:t('Competition','Конкуренция'),technology:t('Technology','Технологии'),supply_chain:t('Supply chain','Цепочки поставок'),markets:t('Markets & FX','Рынки и валюта')}))
const chartData=computed(()=>{const ds=Array.from({length:7},(_,i)=>new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10));return{labels:ds.map(d=>fmt(d,{weekday:'short'})),datasets:[{label:t('Risk signals','Риски'),data:ds.map(d=>state.events.filter(e=>(e.published_at||e.created_at).startsWith(d)&&e.sentiment==='risk').length),backgroundColor:'#b15cc5',borderRadius:4,barPercentage:.55},{label:t('Opportunities','Возможности'),data:ds.map(d=>state.events.filter(e=>(e.published_at||e.created_at).startsWith(d)&&e.sentiment==='opportunity').length),backgroundColor:'#b6d8c7',borderRadius:4,barPercentage:.55},{label:t('Other signals','Другие сигналы'),data:ds.map(d=>state.events.filter(e=>(e.published_at||e.created_at).startsWith(d)&&!['risk','opportunity'].includes(e.sentiment)).length),backgroundColor:'#ded0e8',borderRadius:4,barPercentage:.55}]}})
const stats=computed(()=>[{label:t('Relevant signals','Значимые сигналы'),value:String(state.events.length).padStart(2,'0'),icon:'Radar',tone:'purple',note:t('In the last 30 days','За последние 30 дней')},{label:t('Needs your attention','Требуют внимания'),value:String(high.value.length).padStart(2,'0'),icon:'CircleAlert',tone:'amber',note:t('Relevance of 80% or higher','Релевантность от 80%')},{label:t('Opportunities spotted','Найдено возможностей'),value:String(opportunities.value.length).padStart(2,'0'),icon:'ArrowUpRight',tone:'green',note:t('Potential moves to explore','Возможные направления действий')},{label:t('Evidence sources','Источников в событиях'),value:String(sourceCount.value).padStart(2,'0'),icon:'Layers',tone:'blue',note:t('Underlying event evidence','Источники использованных фактов')}])
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('YOUR BUSINESS, IN CONTEXT','ВАШ БИЗНЕС В КОНТЕКСТЕ')}}</span><h1>{{t('The bigger picture.','Общая картина.')}}</h1><p>{{t('What’s changing around your business, and what deserves your attention.','Что меняется вокруг вашего бизнеса и что заслуживает внимания.')}}</p></div><div class="row gap-sm"><RouterLink to="/briefs" class="btn secondary"><Icon name="FileText" :size="16"/>{{t('Read your brief','Ваша сводка')}}</RouterLink><button v-if="writeAccess" class="btn primary" @click="runAnalysis" :disabled="!!activeJob"><Icon name="RefreshCw" :size="16"/>{{t('Run monitoring','Запустить мониторинг')}}</button></div></div>
<div class="stats-grid"><article class="stat-card" v-for="s in stats" :key="s.label"><div class="row between"><span>{{s.label}}</span><span class="stat-icon" :class="s.tone"><Icon :name="s.icon" :size="18"/></span></div><strong>{{s.value}}</strong><small>{{s.note}}</small></article></div>
<div class="dashboard-charts"><section class="card trend-card"><div class="card-heading"><div><h2>{{t('The signal landscape','Динамика сигналов')}}</h2><p>{{t('A week of developments, through your company’s lens.','События недели через призму вашей компании.')}}</p></div><span class="period-label"><Icon name="Calendar" :size="14"/>{{t('Last 7 days','Последние 7 дней')}}</span></div><div class="chart-legend"><span><i style="background:#b15cc5"></i>{{t('Risks','Риски')}}</span><span><i style="background:#b6d8c7"></i>{{t('Opportunities','Возможности')}}</span><span><i style="background:#ded0e8"></i>{{t('Other signals','Другие сигналы')}}</span></div><div class="chart-container"><Chart :data="chartData" :options="{scales:{x:{grid:{display:false},border:{display:false},ticks:{color:'#96909b',font:{size:11}}},y:{beginAtZero:true,grid:{color:state.theme==='dark'?'#302b35':'#f0edf3'},border:{display:false},ticks:{precision:0,color:'#96909b',stepSize:1}}}}"/></div></section>
<section class="card focus-card"><div class="card-heading"><div><h2>{{t('Where the impact is','Где сосредоточено влияние')}}</h2><p>{{t('Your signals by business driver','Сигналы по факторам бизнеса')}}</p></div><Icon name="ChartDonut" class="muted"/></div><div class="focus-body"><div class="donut" :style="{background:state.events.length?'conic-gradient(#a24cb8 0% '+(risks.length/state.events.length*100)+'%, #b6d8c7 '+(risks.length/state.events.length*100)+'% '+((risks.length+opportunities.length)/state.events.length*100)+'%, #e7daee 0%)':'var(--border)'}"><div><strong>{{state.events.length}}</strong><span>{{t('signals','сигналов')}}</span></div></div><div class="focus-categories"><div v-for="(c,i) in categories.slice(0,4)" :key="String(c[0])"><span class="category-dot" :style="{background:['#a24cb8','#bd87cc','#b6d8c7','#c5bfda'][i]}"></span><span>{{labels[String(c[0])]||c[0]}}</span><strong>{{c[1]}}</strong></div><p v-if="!categories.length" class="small muted">{{t('Your first run will map your signal landscape.','Первый анализ покажет распределение сигналов.')}}</p></div></div></section></div>
<div class="dashboard-lower"><section><div class="section-heading"><div><span class="eyebrow">{{t('YOUR DECISION QUEUE','ВАША ПОВЕСТКА РЕШЕНИЙ')}}</span><h2>{{t('Worth a closer look','Стоит присмотреться')}}</h2></div><RouterLink to="/events" class="text-link">{{t('All signals','Все сигналы')}}<Icon name="ArrowRight" :size="15"/></RouterLink></div><div v-if="state.events.length" class="event-list"><EventCard v-for="e in state.events.slice(0,3)" :key="e.id" :event="e"/></div><div v-else class="card empty"><span class="empty-icon"><Icon name="Radar" :size="30"/></span><h3>{{t('Your first signal is ahead.','Первый сигнал ещё впереди.')}}</h3><p>{{t('Add sources and run monitoring to connect the news to your company’s priorities.','Добавьте источники и запустите мониторинг, чтобы связать новости с приоритетами компании.')}}</p><RouterLink to="/sources" class="btn primary">{{t('Set up monitoring','Настроить мониторинг')}}<Icon name="ArrowRight" :size="15"/></RouterLink></div></section>
<aside><div class="section-heading"><div><span class="eyebrow">{{t('FROM INSIGHT TO ACTION','ОТ ВЫВОДА К ДЕЙСТВИЮ')}}</span><h2>{{t('Your next moves','Следующие шаги')}}</h2></div><span class="spark-icon"><Icon name="Sparkles" :size="18"/></span></div><div class="card moves-card"><button v-for="(e,i) in state.events.slice(0,3)" :key="e.id" class="next-move" @click="state.selectedEvent=e"><span class="move-number">0{{i+1}}</span><div><span class="tiny muted">{{t('SUGGESTED ACTION','РЕКОМЕНДУЕМЫЙ ШАГ')}}</span><p>{{(e[state.locale]||e.en).actions[0]}}</p><span class="text-link small">{{t('See the reasoning','Посмотреть основания')}}<Icon name="ArrowUpRight" :size="13"/></span></div></button><div v-if="!state.events.length" class="empty compact-empty"><Icon name="ListChecks"/><p>{{t('Actions will appear with your first verified insights.','Действия появятся с первыми проверенными выводами.')}}</p></div><div class="moves-foot"><Icon name="Info" :size="14"/><span>{{t('Decision support. Verify assumptions before acting.','Поддержка решений. Проверьте предположения до действий.')}}</span></div></div><RouterLink to="/assistant" class="assistant-promo"><span class="spark-icon"><Icon name="Sparkles" :size="21"/></span><div><h3>{{t('A question on your mind?','Есть вопрос?')}}</h3><p>{{t('Explore the why behind the signal.','Разберитесь в причинах сигнала.')}}</p></div><Icon name="ArrowUpRight" :size="20"/></RouterLink></aside></div>
</template>
